import 'dart:convert';
import 'package:flutter/foundation.dart';
import '../models/university.dart';

const String _b64 = '';

final List<University> universitiesList = _decodeUniversities();

List<University> _decodeUniversities() {
  try {
    final rawJson = utf8.decode(base64Decode(_b64));
    final List<dynamic> list = jsonDecode(rawJson);
    return list.map((e) => University.fromMap(e as Map<String, dynamic>)).toList();
  } catch (e) {
    debugPrint('Error decoding universities: $e');
    return [];
  }
}
